// Writes examples/arduino/CustomWidget/sun_dial.h from
// examples/elements/sun-dial.js, so the sketch serves the element from
// flash (WebUi::asset). Run by `pnpm build`; CI checks it's current.
import { readFileSync, writeFileSync } from 'node:fs';

const src = new URL('../../examples/elements/sun-dial.js', import.meta.url);
const out = new URL('../../examples/arduino/CustomWidget/sun_dial.h', import.meta.url);
const js = readFileSync(src, 'utf8');
if (js.includes(')js"')) throw new Error('sun-dial.js would end the raw string literal');
writeFileSync(
  out,
  `#pragma once
// Generated by web/scripts/elements.mjs from examples/elements/sun-dial.js.
// Do not edit.
static const char kSunDial[] = R"js(${js})js";
`,
);
console.log('wrote examples/arduino/CustomWidget/sun_dial.h');
